// ============================================================================
// MÓDULO Icono — ícono de la app para el acceso directo del teléfono y la
// pestaña del navegador. La imagen va aquí mismo (PNG 192x192 en base64); la
// primera vez que se abre la app se guarda en Drive como archivo público y su
// enlace se recuerda en las propiedades del script. Si alguien borra el archivo
// de Drive, se vuelve a crear solo.
// ============================================================================

var ICONO_APP_PNG_B64 = '';

function urlIconoApp_() {
  var props = PropertiesService.getScriptProperties();
  var id = props.getProperty('ICONO_APP_ID');
  if (!id) {
    var blob = Utilities.newBlob(Utilities.base64Decode(ICONO_APP_PNG_B64), 'image/png', 'Icono Bitacora MM103.png');
    var archivo = DriveApp.createFile(blob);
    archivo.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    id = archivo.getId();
    props.setProperty('ICONO_APP_ID', id);
  }
  return 'https://drive.google.com/uc?id=' + id + '&export=download&format=png';
}

/** Para volver a generar el ícono (por ejemplo, si se cambia la imagen de arriba). */
function regenerarIconoApp() {
  PropertiesService.getScriptProperties().deleteProperty('ICONO_APP_ID');
  return urlIconoApp_();
}
